    def _first_difference(a, b, path):
        if isinstance(a, dict):
            for key in a:
                found = _first_difference(
                    a[key], b[key], path + "." + key
                )
                if found is not None:
                    return found
            return None
        if isinstance(a, list):
            if len(a) != len(b):
                return path + ".length"
            for i, (a_item, b_item) in enumerate(zip(a, b)):
                found = _first_difference(
                    a_item, b_item, path + "[%d]" % i
                )
